Given an integer array arr[], find all the subsets of the array. A subset is any selection from an array, where the order does not matter, and no element appears more than once. A subset can include any number of elements, from none (the empty subset) to all.Input: arr[] = [1, 2, 3]Output: [[], [1], [1, 2], [1, 2, 3], [1, 3], [2], [2, 3], [3]]Explanation: The subsets of [1, 2, 3] are: [[], [1], [1, 2], [1, 2, 3], [1, 3], [2], [2, 3], [3]]Input: arr[] = [2, 4]Output: [[], [2], [2, 4], [4]]Explanation: The subsets of [2, 4] are: [[], [2], [2, 4], [4]]Try It YourselfTable of ContentUsing RecursionUsing Bit ManipulationNumber of Subsets of an array of size n = 2nProof: For each element of the array we have 2 choices:Choice 1: Include it into the subset.Choice 2: Exclude it from the subset. Since, each element has 2 choice to contribute into the subset and we have total n elements, therefore total subsets = 2nUsing RecursionThe idea is to explore possible choices one by one recursively. For each element, there two options, either include it into subset or exclude it. State Space Tree for printing all subsets using Backtracking:Suppose an array of size 3 having elements [1, 2, 3], the state space tree can be constructed as below: 
            C++

    #include <iostream>
#include <vector>
#include <algorithm> 
using namespace std;

void subsetRecur(int i, vector<int>& arr, 
       vector<vector<int>>& res, vector<int>& subset) {

    // add subset at end of array
    if (i == arr.size()) {
        res.push_back(subset);
        return;
    }

    // include the current value and 
    // recursively find all subsets
    subset.push_back(arr[i]);
    subsetRecur(i+1, arr, res, subset);

    // exclude the current value and 
    // recursively find all subsets.
    subset.pop_back();
    subsetRecur(i+1, arr, res, subset);
}

vector<vector<int> > subsets(vector<int>& arr) {

    vector<int> subset;
    vector<vector<int>> res;

    // finding recursively
    subsetRecur(0, arr, res, subset);
    return res;
}

int main() {
    vector<int> arr = { 1, 2, 3 };
    vector<vector<int> > res = subsets(arr);

    for (int i = 0; i < res.size(); i++) {
        cout << "[";
        for (int j = 0; j < res[i].size(); j++) {
            cout << res[i][j];
            if (j != res[i].size() - 1) cout << ", ";
        }
        cout << "]" << endl;
    }

    return 0;
}


