Time Complexity: O(n * 2n), generating all subsets requires 2n recursive calls, and copying each subset of size up to n takes O(n) time.Auxiliary Space: O(n), recursion stack and temporary subset use at most n space at a time.Using Bit ManipulationThis approach is simpler compared to backtracking, as it just requires basic knowledge of bits.Each element in an array has only two choices: it can either be included or excluded from a subset. We can represent these choices using bits: 0 means excluded, and 1 means included. The i-th bit corresponds to the i-th element of the array.For an array of size n, there are 2n possible subsets, and each subset can be uniquely represented by the bit representation of numbers from 0 to 2n - 1.Example: Consider an array [A, B]:0 → 00 → A excluded, B excluded → []1 → 01 → A excluded, B included → [B]2 → 10 → A included, B excluded → [A]3 → 11 → A included, B included → [A, B]Illustration:Suppose given an array of size 3 = [1, 2, 3]. Generate all the subsets using bit manipulation as shown in the image below:
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

vector<vector<int>> subsets(vector<int> &arr) {
    int n = arr.size();
    vector<vector<int>> res;

    // Loop through all possible subsets
    for (int i = 0; i < (1 << n); i++) {
        vector<int> subset;

        // Loop through all elements of the input array
        for (int j = 0; j < n; j++) {

            // Check if the jth bit is set 
            if ((i & (1 << j)) != 0) {
                subset.push_back(arr[j]);
            }
        }

        // Push the subset into result
        res.push_back(subset);
    }

    return res;
}

int main() {
    vector<int> arr = { 1, 2, 3 };
    vector<vector<int> > res = subsets(arr);
    for (int i = 0; i < res.size(); i++) {
        cout << "[";
        for (int j = 0; j < res[i].size(); j++) {
            cout << res[i][j];
            if (j != res[i].size() - 1) cout << ", ";
        }
        cout << "]" << endl;
    }

    return 0;
}


